   736|      secret: metadata.secret,
   737|      status,
   738|      saved: isPresent,
   739|      presentInRuntime: envPresence.present,
   740|      runtimeSource: envPresence.source,
   741|      lastTestedAt: row?.last_tested_at ?? null,
   742|      maskedPreview: row?.masked_preview ?? envPresence.maskedPreview ?? null,
   743|      description: metadata.description,
