   749|function buildProviderReadiness(rows: OwnerVariableRow[]): Record<OwnerVariableProvider, ProviderReadiness> {
   750|  const rowByName = new Map(rows.map((row) => [row.name, row]));
   751|  const providers = Array.from(new Set(OWNER_VARIABLES.map((item) => item.provider))) as OwnerVariableProvider[];
   752|  return Object.fromEntries(providers.map((provider) => {
   753|    const required = OWNER_VARIABLES.filter((item) => item.provider === provider && item.required).map((item) => item.name);
   754|    // A required variable is satisfied if it's in the encrypted store OR in the backend runtime env.
   755|    const saved = required.filter((name) => rowByName.has(name) || readEnv(name));
   756|    const missing = required.filter((name) => !rowByName.has(name) && !readEnv(name));
   757|    const providerRows = OWNER_VARIABLES.filter((item) => item.provider === provider).map((item) => rowByName.get(item.name)).filter((row): row is OwnerVariableRow => Boolean(row));
   758|    const hasInvalid = providerRows.some((row) => row.status === 'invalid');
   759|    const hasTested = required.length > 0 && required.every((name) => rowByName.get(name)?.status === 'tested');
   760|    const lastTestedAt = providerRows
   761|      .map((row) => row.last_tested_at)
   762|      .filter((value): value is string => Boolean(value))
   763|      .sort()
   764|      .at(-1) ?? null;
   765|    const status: ProviderReadiness['status'] = missing.length > 0 ? 'missing' : hasInvalid ? 'invalid' : hasTested ? 'tested' : 'saved';
   766|    return [provider, {
   767|      provider,
   768|      status,
   769|      requiredVariableNames: required,
   770|      savedVariableNames: saved,
   771|      missingVariableNames: missing,
   772|      lastTestedAt,
   773|      secretValuesReturned: false as const,
   774|    }];
   775|  })) as Record<OwnerVariableProvider, ProviderReadiness>;
