   778|async function buildStoredSecretMap(): Promise<StoredSecretMap> {
   779|  const rows = await listStoredRows();
   780|  const output: StoredSecretMap = {};
   781|  for (const row of rows) {
   782|    const name = row.name;
   783|    if (!isAllowedVariableName(name)) {
   784|      continue;
   785|    }
   786|    const decrypted = tryDecryptRowValue(row);
   787|    if (!decrypted) {
   788|      // Stale key / rotated: skip this row so one undecryptable value
   789|      // cannot abort the entire provider test. The runtime bridge will
   790|      // log it; the variable reports as unreadable rather than crashing.
   791|      console.log('[IVXOwnerVariables] buildStoredSecretMap: skipping undecryptable row', { name, maskedPreview: row.masked_preview });
   792|      continue;
   793|    }
   794|    output[name] = decrypted.plaintext;
   795|  }
   796|  return output;
