   799|/**
   800| * Reads one encrypted Owner Variable for backend runtime use without exposing it to API responses.
   801| */
   802|export async function getIVXOwnerVariableRuntimeValue(
   803|  name: OwnerVariableName,
   804|  options: { preferStored?: boolean } = {},
   805|): Promise<string> {
   806|  const envValue = readEnv(name);
   807|  if (envValue && !options.preferStored) return envValue;
   808|  try {
   809|    const row = await getStoredRow(name);
   810|    if (!row) return envValue;
   811|    const decrypted = tryDecryptRowValue(row);
   812|    if (!decrypted) {
   813|      console.log('[IVXOwnerVariables] Runtime value bridge: decryption failed for all key candidates', {
   814|        name,
   815|        maskedPreview: row.masked_preview,
   816|      });
   817|      return '';
   818|    }
   819|    // Auto-reencrypt with the primary key if a fallback key was used (key rotation)
   820|    if (decrypted.keyIndex > 0) {
   821|      const plaintext = decrypted.plaintext.trim();
   822|      try {
   823|        await reencryptStoredRow(name, plaintext);
   824|        console.log('[IVXOwnerVariables] Runtime value bridge: re-encrypted stale-key row with primary key', {
   825|          name,
   826|          keyIndex: decrypted.keyIndex,
   827|        });
   828|      } catch (reencryptError) {
   829|        console.log('[IVXOwnerVariables] Runtime value bridge: re-encryption failed (returning decrypted value anyway)', {
   830|          name,
   831|          message: reencryptError instanceof Error ? sanitizeExternalErrorDetail(reencryptError.message) : 'unknown',
   832|        });
   833|      }
   834|      return plaintext;
   835|    }
   836|    return decrypted.plaintext.trim();
   837|  } catch (error) {
   838|    console.log('[IVXOwnerVariables] Runtime REST value bridge unavailable; trying direct Postgres fallback:', {
   839|      name,
   840|      message: error instanceof Error ? sanitizeExternalErrorDetail(error.message) : 'unknown',
   841|    });
   842|    if (getDatabaseUrl()) {
   843|      try {
