   116|async function storeAwsCredentialsInDb(creds: AwsCredentials): Promise<boolean> {
   117|  try {
   118|    const { createClient } = await import('@supabase/supabase-js');
   119|    const url = readEnv('EXPO_PUBLIC_SUPABASE_URL') || readEnv('SUPABASE_URL');
   120|    const key = readEnv('SUPABASE_SERVICE_ROLE_KEY') || readEnv('SUPABASE_SERVICE_KEY');
   121|    if (!url || !key) return false;
   122|    const sb = createClient(url, key, { auth: { autoRefreshToken: false, persistSession: false } });
   123|    const entries = [
   124|      { name: 'AWS_ACCESS_KEY_ID', value: creds.accessKeyId },
   125|      { name: 'AWS_SECRET_ACCESS_KEY', value: creds.secretAccessKey },
   126|      { name: 'AWS_REGION', value: creds.region || 'us-east-1' },
   127|      { name: 'S3_BUCKET_NAME', value: creds.bucket || 'ivxholding.com' },
   128|      { name: 'CLOUDFRONT_DISTRIBUTION_ID', value: creds.cloudFrontDistributionId || '' },
   129|    ];
   130|    for (const entry of entries) {
   131|      if (!entry.value) continue;
   132|      const { error } = await sb.from('ivx_owner_variables').upsert({
   133|        name: entry.name,
   134|        encrypted_value: entry.value,
   135|        masked_preview: entry.value.substring(0, 4) + '****',
   136|        updated_at: new Date().toISOString(),
   137|      }, { onConflict: 'name' });
   138|      if (error) console.log(`[LandingFullDeploy] Failed to store ${entry.name}: ${error.message}`);
   139|    }
   140|    return true;
   141|  } catch (err) {
   142|    console.log(`[LandingFullDeploy] storeAwsCredentialsInDb error: ${err instanceof Error ? err.message : String(err)}`);
   143|    return false;
   144|  }
