   149|  const types: Record<string, string> = {
   150|    'html': 'text/html; charset=utf-8',
   151|    'js': 'application/javascript; charset=utf-8',
   152|    'css': 'text/css; charset=utf-8',
   153|    'json': 'application/json; charset=utf-8',
