   169|function getCacheControl(filename: string): string {
   170|  if (filename === 'index.html') return 'no-cache, no-store, must-revalidate';
   171|  if (filename === 'ivx-config.json') return 'no-cache, no-store, must-revalidate';
   172|  if (filename === 'robots.txt' || filename === 'sitemap.xml') return 'public, max-age=3600';
   173|  // JS/CSS assets — short cache since they change with deploys
   174|  if (filename.endsWith('.js') || filename.endsWith('.css')) return 'public, max-age=300, s-maxage=600, stale-while-revalidate=1200';
   175|  return 'public, max-age=3600';
